package wgmodern;
import java.util.UUID;import com.mojang.authlib.GameProfile;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.minecraftforge.gametest.*;import net.minecraftforge.common.util.FakePlayerFactory;import net.minecraft.resources.ResourceLocation;import tc4revival.research.KnowledgeSavedData;
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class MiscServerTests {
 @GameTest(template="empty") public static void brainJerkyPreservesLegacyResearchRollsAndFoodValues(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("f9301967-a657-4388-a5b1-10909b0bff34"),"WGFoodTester"));var data=KnowledgeSavedData.get(h.getLevel().getServer());data.ensure(p.getUUID(),n->0);var before=data.snapshot(p.getUUID()).orElseThrow();int prior=before.knownAspects().values().stream().mapToInt(Integer::intValue).sum();p.getFoodData().setFoodLevel(5);var stack=new ItemStack(Content.BRAINJERKY.get(),2);stack.getItem().finishUsingItem(stack,h.getLevel(),p);int after=data.snapshot(p.getUUID()).orElseThrow().knownAspects().values().stream().mapToInt(Integer::intValue).sum();h.assertTrue(after-prior>=1&&after-prior<=6,"One to three independent rolls award one or two points each");h.assertTrue(stack.getCount()==1&&p.getFoodData().getFoodLevel()==11,"Brain jerky consumes one item and restores six hunger");h.assertTrue(Content.NETHERCAKE.get().getFoodProperties().getSaturationModifier()==1.5f&&Content.SWEETWART.get().getFoodProperties().getNutrition()==2,"Original cake and sweetwart values retained");pass(h);}
 @GameTest(template="empty") public static void bootsAndAliasesUseOriginalRules(GameTestHelper h){var boots=new ItemStack(tc4revival.content.TCItems.TRAVELLER_BOOTS.get());h.assertTrue(boots.getItem().isValidRepairItem(boots,new ItemStack(Items.LEATHER)),"WG enables leather repair on Traveller boots");h.assertTrue(!boots.getItem().isValidRepairItem(boots,new ItemStack(Items.IRON_INGOT)),"Unrelated repair ingredient rejected");for(var alias:ResearchAliases.ALL){var fake=tc4revival.research.ResearchCatalogs.catalog().require(ResearchAliases.key(alias.original()));h.assertTrue(fake.parents().isEmpty()&&!fake.has(tc4revival.research.ResearchDefinition.Flag.HIDDEN),"Mirror is a visible reference, not a gated duplicate");var knowledge=new tc4revival.research.PlayerKnowledge(tc4revival.aspect.TCAspects.catalog());knowledge.rememberResearch(alias.original());h.assertTrue(tc4revival.research.ResearchCatalogs.rules().completed(knowledge,fake.key())&&!knowledge.researchMarkers().contains(fake.key()),"Mirror reads original completion without extra markers");}pass(h);}
 @GameTest(template="empty") public static void equippedPouchWritesThroughAndCannotFollowReplacement(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("29d0c04b-4d20-4318-87ca-58b0b4c6b2f7"),"WGPouchTester"));var inventory=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).resolve().orElseThrow();var belt=inventory.getStacksHandler("belt").orElseThrow();var pouch=new ItemStack(tc4revival.content.TCItems.FOCUS_POUCH.get());belt.getStacks().setStackInSlot(0,pouch);var menu=new EquippedPouchMenu(1,p.getInventory(),"belt",0);var focusItem=net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(new ResourceLocation("thaumcraft","focus_fire"));var focus=new ItemStack(focusItem);h.assertTrue(menu.stillValid(p)&&menu.slots.get(0).mayPlace(focus)&&!menu.slots.get(0).mayPlace(new ItemStack(Items.DIRT)),"Equipped menu admits only focuses");menu.contents.setItem(17,focus);h.assertTrue(tc4revival.content.FocusPouchItem.contents(pouch).get(17).is(focusItem),"Last slot persists immediately");var replacement=new ItemStack(tc4revival.content.TCItems.FOCUS_POUCH.get());belt.getStacks().setStackInSlot(0,replacement);h.assertTrue(!menu.stillValid(p),"Replacing the equipped pouch invalidates its old menu");menu.contents.setItem(17,ItemStack.EMPTY);h.assertTrue(tc4revival.content.FocusPouchItem.contents(pouch).get(17).is(focusItem)&&tc4revival.content.FocusPouchItem.contents(replacement).get(17).isEmpty(),"Stale menu cannot edit either displaced or replacement pouch");belt.getStacks().setStackInSlot(0,ItemStack.EMPTY);pass(h);}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
